/**
 * WordPress dependencies
 */
import domReady from '@safe-wordpress/dom-ready';
import '@safe-wordpress/notices';
import { render } from '@safe-wordpress/element';

/**
 * External dependencies
 */
import { registerCoreExperiments } from '@nab/experiment-library';
import { registerCommands } from '@nab/commands';
import {
	PreviewUrlButton,
	TestCreationButtons,
	TitleAction,
} from '@nab/components';
import { createStagingNotice } from '@nab/utils';
import type { SubscriptionPlan } from '@nab/types';

/**
 * Internal dependencies
 */
import './style.scss';
import { renderHelp } from './help';
import { Layout } from './components/layout';
import { ExperimentSection } from './components/experiment-section';
import { OptimizationScoreAndQuota } from './components/optimization-score-and-quota';
import { RecommendationSection } from './components/recommendation-section';
import { NoQuotaWarning } from './components/no-quota-warning';

type Settings = {
	readonly staging: 'environment-type' | 'url' | false;
	readonly subscription: SubscriptionPlan | false;
};

export function initPage( id: string, settings: Settings ): void {
	registerCoreExperiments();
	domReady( () => registerCommands() );

	const { staging, subscription } = settings;

	const titleAction = document.getElementById( `${ id }-title-action` );
	const content = document.getElementById( id );

	createStagingNotice( staging );
	render(
		<>
			<TestCreationButtons disableAi />
			<TitleAction isSubscribed={ !! subscription } />
			<PreviewUrlButton />
		</>,
		titleAction
	);

	render(
		<Layout>
			<NoQuotaWarning />
			<OptimizationScoreAndQuota />
			<RecommendationSection />
			<ExperimentSection />
		</Layout>,
		content
	);

	renderHelp();
}
